		var x = pt.x;
		var y = pt.y;
		if(opaque) {
			var e = Assets.tiles.addBatchElement(this.hudLayer,"hudSquare" + (ok ? "Ok" : "No"),0,0.5,0.5);
			e.x = x + w * 0.5;
			e.y = y - h * 0.5;
			var v = w - p * 2 - 40;
			if(e.t != null && e.t.width > 0) {
				e.scaleX = v / e.t.width;
			}
			var v = h - p * 2 - 40;
			if(e.t != null && e.t.height > 0) {
				e.scaleY = v / e.t.height;
			}
		}
		var e = Assets.tiles.addBatchElement(this.hudLayer,"squareOrange",0,0.5,0.5);
		e.x = x + w * 0.5;
		e.y = y - h * 0.5;
		var v = w - p * 2 - 40;
		if(e.t != null && e.t.width > 0) {
			e.scaleX = v / e.t.width;
		}
		var v = h - p * 2 - 40;
		if(e.t != null && e.t.height > 0) {
			e.scaleY = v / e.t.height;
		}
		var e = Assets.tiles.addBatchElement(this.hudLayer,"enluminure",0);
		e.x = x + p;
		e.y = y - h + p;
		var e = Assets.tiles.addBatchElement(this.hudLayer,"enluminure",0);
		e.x = x + w - p;
		e.y = y - h + p;
		e.rotation = 1.5707963267948966;
		var e = Assets.tiles.addBatchElement(this.hudLayer,"enluminure",0);
		e.x = x + w - p;
		e.y = y - p;
		e.rotation = 3.1415926535897932384626433832795;
		var e = Assets.tiles.addBatchElement(this.hudLayer,"enluminure",0);
