Lang.getQuestObjective = function(sid,id,param,n,shotel) {
	if(id == null) {
		id = sid;
	}
	var str;
	switch(id) {
	case "Bedroom":
		str = Lang.t.get("Have ::n:: bedrooms in your hotel",{ _n : n});
		break;
	case "Beer":
		str = Lang.t.get("Serve Soda to your clients",null);
		break;
	case "Boost":
		str = Lang.t.get("Use turbo boost",null);
		break;
	case "CompleteDailyQuestBugged":
		str = "???";
		break;
	case "ExactHappiness":
		str = Lang.t.get("Have ::n:: clients with EXACTLY ::h:: happiness at the same time in your hotel",{ _n : n, _h : param});
		break;
	case "HappinessColumn":
		str = Lang.t.get("Have ::n:: clients with exactly ::h:: happiness in a single column",{ _n : n, _h : param});
		break;
	case "HappinessCombo":
		str = Lang.t.get("Make ::n:: clients happy in one move",{ _n : n});
		break;
	case "HappinessLine":
		str = Lang.t.get("Have ::n:: clients with exactly ::h:: happiness in a single row",{ _n : n, _h : param});
		break;
	case "InstallClient":
		str = Lang.t.get("Install clients in bedrooms",null);
		break;
	case "Laundry":
		str = Lang.t.get("Wash client clothes",null);
		break;
	case "Love":
		str = Lang.t.get("Give love to your clients",null);
		break;
	case "MaxedHappiness":
		str = Lang.t.get("Have ::c:: clients with ::n::+ happiness",{ _c : n, _n : shotel.getMaxHappiness()});
		break;
	case "MinHappiness":
		str = Lang.t.get("Have ::n:: clients with AT LEAST ::h:: happiness at the same time in your hotel",{ _n : n, _h : param});
		break;
	case "Paper":
		str = Lang.t.get("Use toilet paper",null);
		break;
	case "Soap":
		str = Lang.t.get("Use soap",null);
		break;
	case "Theft":
		str = Lang.t.get("Steal money to your clients",null);
		break;
	case "Trash":
		str = Lang.t.get("Send clients to the Trash",null);
		break;
	case "UseItem":
		str = Lang.t.get("Use ::item:: on installed clients",{ _item : Lang.getItem(Type.createEnumIndex(com_Item,param)).name});
		break;
	case "Vip":
		str = Lang.t.get("Completely satisfy ::n:: VIP",{ _n : n});
		break;
	}
	return mt_Utf8.addNbsps(str);
};
