	,_drag: function(getX,getY,getTX,getTY,fromIsNotOnScene,fadeAway) {
		if(fadeAway == null) {
			fadeAway = false;
		}
		if(fromIsNotOnScene == null) {
			fromIsNotOnScene = false;
		}
		var _gthis = this;
		var ts = 1;
		var hand = Assets.tiles.h_get("tutoHand");
		this.wrapper.add(hand,0);
		var xRatio = 20 / hand.get_tile().width;
		var yRatio = 20 / hand.get_tile().height;
		var _this = hand.pivot;
		_this.centerFactorX = xRatio;
		_this.centerFactorY = yRatio;
		_this.usingFactor = true;
		_this.isUndefined = false;
		var v = hand.scaleX * ts;
		hand.posChanged = true;
		hand.scaleX = v;
		var v = hand.scaleY * ts;
		hand.posChanged = true;
		hand.scaleY = v;
		var ratio = 0.0;
		var spd = 0.;
		var phase = 0;
		this.get_game().viewport.focus(getX() + (getTX() - getX()) * 0.5,getY() + (getTY() - getY()) * 0.5);
		this.createChildProcess(function(p) {
			if(getX() == null || getTX() == null) {
				return;
			}
			var from = fromIsNotOnScene ? { x : getX(), y : getY()} : Game.ME.sceneToUi(getX(),getY());
			var to = Game.ME.sceneToUi(getTX(),getTY());
			var a = Math.atan2(to.y - from.y,to.x - from.x);
			var ax = from.x;
			var ay = from.y;
			var bx = to.x;
			var by = to.y;
			var d = Math.sqrt((ax - bx) * (ax - bx) + (ay - by) * (ay - by));
			if((_gthis.ftime | 0) % 15 == 0 && !_gthis.get_game().isDragging() && !ui_SideMenu.isDragging()) {
				_gthis.get_game().uiFx.tapDrag(from.x,from.y);
			}
			if(phase == 0) {
				var _tween = _gthis.tw.create_(function() {
					return hand.scaleX;
				},function(_setV) {
					hand.posChanged = true;
					hand.scaleX = _setV;
				},null,0.7 * ts,null,350);
				var a1 = _tween;
				a1.onUpdate = function() {
					var v = hand.scaleX;
					hand.posChanged = true;
					hand.scaleY = v;
				};
				a1.onEnd = function() {
					phase = 2;
				};
				phase = 1;
			}
			if(phase == 2) {
				ratio += spd;
				if(ratio <= 0.2) {
					spd += 0.005;
				}
				if(ratio >= 0.8 && spd >= 0.01) {
					spd *= 0.85;
				}
				if(ratio >= 1) {
					phase = 3;
					var _tween = _gthis.tw.create_(function() {
						return hand.scaleX;
					},function(_setV) {
						hand.posChanged = true;
						hand.scaleX = _setV;
					},null,1.1 * ts,null,200);
					var a1 = _tween;
					a1.onUpdate = function() {
						var v = hand.scaleX;
						hand.posChanged = true;
						hand.scaleY = v;
					};
					a1.onEnd = function() {
						phase = 0;
						ratio = 0;
					};
				}
				if(!fadeAway) {
					Game.ME.uiFx.dragDust(a,hand.x,hand.y);
				}
			}
			if(fadeAway) {
				var b = 1 - ratio * 1.6;
				hand.alpha = 0 > b ? 0 : b;
			}
			var v = from.x + Math.cos(a) * ratio * d;
			hand.posChanged = true;
			hand.x = v;
			var v = from.y + Math.sin(a) * ratio * d;
			hand.posChanged = true;
			hand.y = v;
		},function(p) {
			_gthis.tw.terminate_(function() {
				return hand.scaleX;
			},function(_setV) {
				hand.posChanged = true;
				hand.scaleX = _setV;
			},false);
			hand.dispose();
		},true);
	}
